tinue; if ($svc) { Set-Service -Name 'OneSyncSvc' -StartupType 'Manual' -ErrorAction SilentlyContinue; Write-Host 'Restaurado: OneSyncSvc -> Manual' } $svc = Get-Service -Name 'UnistoreSvc' -ErrorAction SilentlyContinue; if ($svc) { Set-Service -Name 'UnistoreSvc' -StartupType 'Manual' -ErrorAction SilentlyContinue; Write-Host 'Restaurado: UnistoreSvc -> Manual' } $svc = Get-Service -Name 'LicenseManager' -ErrorAction SilentlyContinue; if ($svc) { Set-Service -Name 'LicenseManager' -StartupType 'Manual' -ErrorAction SilentlyContinue; Write-Host 'Restaurado: LicenseManager -> Manual' } $svc = Get-Service -Name 'DPS' -ErrorAction SilentlyContinue; if ($svc) { Set-Service -Name 'DPS' -StartupType 'Automatic' -ErrorAction SilentlyContinue; Write-Host 'Restaurado: DPS -> Automatic' } $svc = Get-Service -Name 'TrkWks' -ErrorAction SilentlyContinue; if ($svc) { Set-Service -Name 'TrkWks' -StartupType 'Automatic' -ErrorAction SilentlyContinue; Write-Host 'Restaurado: TrkWks -> Automatic' }
